import 'package:flutter/foundation.dart';
enum VoiceRecordingState{idle,recording,cancelArmed,preview,uploading,failed}
final class VoiceRecordingController extends ChangeNotifier{VoiceRecordingState state=VoiceRecordingState.idle;Duration? duration;void start(){state=VoiceRecordingState.recording;notifyListeners();}void updateDrag(double dy){if(state==VoiceRecordingState.recording||state==VoiceRecordingState.cancelArmed){state=dy<=-60?VoiceRecordingState.cancelArmed:VoiceRecordingState.recording;notifyListeners();}}void release(Duration value){if(state==VoiceRecordingState.cancelArmed||value< const Duration(seconds:1)){discard();return;}duration=value>const Duration(seconds:60)?const Duration(seconds:60):value;state=VoiceRecordingState.preview;notifyListeners();}void confirmSend(){if(state==VoiceRecordingState.preview){state=VoiceRecordingState.uploading;notifyListeners();}}void fail(){state=VoiceRecordingState.failed;notifyListeners();}void discard(){duration=null;state=VoiceRecordingState.idle;notifyListeners();}}
